-- Venue Live Guest "Manasik Haji Cinematic" (TK): versi sinematik dari Manasik Haji TK. Aditif & idempoten.
-- Struktur template TIDAK diubah: 8 area bawaan, slot dekor, slot avatar, dan posisi sama dengan manasik-haji-tk;
-- hanya palet, nama area, dan gambar (lukisan venue 1672x941, dekor, avatar) yang baru. Lihat docs/live-manasik-haji-cinematic.md.
-- Jalankan SETELAH admin-live-theme-manasik-haji-tk.sql. Venue NONAKTIF sampai aset di
-- /assets/live-decor/manasik-haji-cinematic/ diunggah; lalu aktifkan lewat Admin > Live Guest > Venue Builder.
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'manasik-haji-cinematic', 'Manasik Haji Cinematic (manasik)', 'manasik',
  coalesce((select jsonb_agg(case e ->> 'id'
      when 'stage' then e || '{"name":"Ka''bah & Panggung Wisuda","icon":"🕋"}'::jsonb
      when 'resepsi' then e || '{"name":"Area Sa''i (Safa–Marwa)","icon":"⛰️"}'::jsonb
      when 'booth' then e || '{"name":"Mini Games Haji","icon":"🎮"}'::jsonb
      when 'galeri' then e || '{"name":"Galeri Madinah","icon":"🕌"}'::jsonb
      when 'video' then e || '{"name":"Video Ucapan Anak","icon":"🎬"}'::jsonb
      when 'buku' then e || '{"name":"Buku Doa & Ucapan","icon":"🤲"}'::jsonb
      when 'kuliner' then e || '{"name":"Kantin & Souvenir Haji","icon":"🎁"}'::jsonb
      when 'istirahat' then e || '{"name":"Perkemahan Mina","icon":"⛺"}'::jsonb
      else e end order by ord)
    from public.live_venues v, jsonb_array_elements(v.areas) with ordinality as t(e, ord) where v.key = 'manasik-haji-tk'),
    (select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb),
  300, false, 108, 'center 38%',
  $t${"name":"Manasik Haji Cinematic","orn":"diamond","ui":{"ivory":"#FBF6E9","white":"#FFFFFF","soft":"#EFE3C8","soft2":"#D9BE8E","accent":"#0F6B4B","deep":"#17130F","ink":"#1F1A14","mute":"#6E6552","line":"#E6DAB8","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FDFAF1","ink":"#1F1A14","accent":"#0F6B4B","gold":"#C9A24A","leaf":"#EFE3C8","hbg":"rgba(251,246,233,.94)","hline":"#D9BE8E","motif":"diamond"},"hud":{"bg":"rgba(23,19,15,.82)","acc":"#E2BC5A","on":"#1F1A14"},"scr":{"wine":"#17130F","veil":"251,246,233"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'manasik-haji-cinematic');
update public.live_venues set decor = $d${"arch":{"url":"/assets/live-decor/manasik-haji-cinematic/arch.webp","w":2.8,"x":6.8,"z":-9,"mirror":true},"sign":{"url":"/assets/live-decor/manasik-haji-cinematic/sign.webp","w":4.2,"x":-16,"z":-25},"easel":{"url":"/assets/live-decor/manasik-haji-cinematic/easel.webp","w":3.6,"x":-6,"z":7.6},"balloons":{"url":"/assets/live-decor/manasik-haji-cinematic/balloons.webp","w":14,"x":0,"z":-27.5},"gifts":{"url":"/assets/live-decor/manasik-haji-cinematic/gifts.webp","w":4.2,"x":-16,"z":-1},"fountain":{"url":"/assets/live-decor/manasik-haji-cinematic/fountain.webp","w":1.6,"x":-8,"z":-2},"stall_drinks":{"url":"/assets/live-decor/manasik-haji-cinematic/stall_drinks.webp","w":6.5,"x":-9,"z":-17},"stall_snacks":{"url":"/assets/live-decor/manasik-haji-cinematic/stall_snacks.webp","w":4.6,"x":17,"z":5},"stall_candy":{"url":"/assets/live-decor/manasik-haji-cinematic/stall_candy.webp","w":5.5,"x":15.5,"z":-25},"claw":{"url":"/assets/live-decor/manasik-haji-cinematic/claw.webp","w":3.6,"x":14.5,"z":-9},"photobooth":{"url":"/assets/live-decor/manasik-haji-cinematic/photobooth.webp","w":4.4,"x":-12,"z":-8},"speakers":{"url":"/assets/live-decor/manasik-haji-cinematic/speakers.webp","w":1.6,"x":-9,"z":-4},"bush":{"url":"/assets/live-decor/manasik-haji-cinematic/bush.webp","w":3.8,"x":16.5,"z":9,"mirror":true},"planter":{"url":"/assets/live-decor/manasik-haji-cinematic/planter.webp","w":1.6,"x":13.5,"z":8,"mirror":true},"lamp":{"url":"/assets/live-decor/manasik-haji-cinematic/lamp.webp","w":0.7,"x":5.0,"z":-2,"mirror":true},"banner":{"url":"/assets/live-decor/manasik-haji-cinematic/banner.webp","w":5.0,"x":13,"z":-17},"rope":{"url":"/assets/live-decor/manasik-haji-cinematic/rope.webp","w":1.4,"x":6.4,"z":-4,"mirror":true},"table":{"url":"/assets/live-decor/manasik-haji-cinematic/table.webp","w":3.6,"x":11,"z":0},"av_host":{"url":"/assets/live-decor/manasik-haji-cinematic/av_host.webp","name":"Jamaah Cilik Berihram"},"av_l1":{"url":"/assets/live-decor/manasik-haji-cinematic/av_l1.webp","name":"Jamaah Putra Ihram"},"av_l2":{"url":"/assets/live-decor/manasik-haji-cinematic/av_l2.webp","name":"Jamaah Putra Berpeci"},"av_l3":{"url":"/assets/live-decor/manasik-haji-cinematic/av_l3.webp","name":"Ustadz Pembimbing"},"av_l4":{"url":"/assets/live-decor/manasik-haji-cinematic/av_l4.webp","name":"Jamaah Putra Tas Selempang"},"av_p1":{"url":"/assets/live-decor/manasik-haji-cinematic/av_p1.webp","name":"Jamaah Putri Hijab Putih"},"av_p2":{"url":"/assets/live-decor/manasik-haji-cinematic/av_p2.webp","name":"Jamaah Putri Mukena"},"av_p3":{"url":"/assets/live-decor/manasik-haji-cinematic/av_p3.webp","name":"Ustadzah Pembimbing"}}$d$::jsonb, background_url = '/assets/live-decor/manasik-haji-cinematic/painting.webp', updated_at = now() where key = 'manasik-haji-cinematic';
